module cpu_datapath(clk, rst, instr, acc, pc);
  input        clk;
  input        rst;
  input  [7:0] instr;
  output [7:0] acc;
  output [3:0] pc;

  reg [7:0] acc_reg;
  reg [3:0] pc_reg;

  wire [1:0] opcode;
  wire [7:0] operand;
  wire       jump_taken;

  assign opcode  = instr[7:6];
  assign operand = {2'b00, instr[5:0]};

  assign jump_taken = (opcode == 2'b11) && (acc_reg != 8'b0);

  always @(posedge clk) begin
    if (rst) begin
      acc_reg <= 8'b0;
      pc_reg  <= 4'b0;
    end else begin
      case (opcode)
        2'b00: begin
          acc_reg <= operand;
        end

        2'b01: begin
          acc_reg <= acc_reg + operand;
        end

        2'b10: begin
          acc_reg <= acc_reg - operand;
        end

        2'b11: begin
          acc_reg <= acc_reg;
        end
      endcase

      if (jump_taken)
        pc_reg <= instr[3:0];
      else
        pc_reg <= pc_reg + 4'd1;
    end
  end

  assign acc = acc_reg;
  assign pc  = pc_reg;

endmodule

